/** Accept only bounded, self-contained PCM WAV clips generated by this client. */
export function voiceAttachment(clip) {
  if (!clip || clip.mime !== 'audio/wav' || typeof clip.data !== 'string' || clip.data.length > 2560060 || !/^[A-Za-z0-9+/]+={0,2}$/.test(clip.data)) {
    throw new Error('El clip de voz no es válido o supera 60 segundos.')
  }
  const bytes = Buffer.from(clip.data, 'base64')
  if (bytes.length < 46 || bytes.length > 1920044 || bytes.toString('ascii', 0, 4) !== 'RIFF' || bytes.toString('ascii', 8, 16) !== 'WAVEfmt ' ||
      bytes.readUInt32LE(4) !== bytes.length - 8 || bytes.readUInt32LE(16) !== 16 || bytes.readUInt16LE(20) !== 1 || bytes.readUInt16LE(22) !== 1 ||
      bytes.readUInt32LE(24) !== 16000 || bytes.readUInt32LE(28) !== 32000 || bytes.readUInt16LE(32) !== 2 || bytes.readUInt16LE(34) !== 16 ||
      bytes.toString('ascii', 36, 40) !== 'data' || bytes.readUInt32LE(40) !== bytes.length - 44 || (bytes.length - 44) % 2) {
    throw new Error('El clip debe ser WAV mono PCM de 16 kHz.')
  }
  return { type: 'file', mime: 'audio/wav', filename: 'mi-voz.wav', url: `data:audio/wav;base64,${bytes.toString('base64')}` }
}
